    #log-list { max-height:165px; overflow:auto; padding:10px; background:#101b30; color:#d8e7ff; border-radius:8px; font:.78rem/1.45 ui-monospace,monospace; white-space:pre-wrap; }
    .step { color:var(--muted); font-size:.85rem; font-weight:700; margin-bottom:9px; }
