*/

const cert = readFileSync("certs/cert.pem", "utf8");
const key = readFileSync("certs/key.pem", "utf8");
const PORT = Number(process.env.PORT || 3000);

const IDLE = 20 * 60_000;
const ABSOLUTE = 8 * 60 * 60_000;
const PREAUTH = 10 * 60_000;
const RECOVERY_LIFE = 30 * 24 * 60 * 60_000;
const LOCKOUT = 10 * 60_000;
const MAX_FAILURES = 5;
const MASTER_KEY = randomBytes(32);
const CSP_NONCE = randomBytes(18).toString("base64");
const BASE32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

type Session = {
  id: string;
  csrf: string;
  accountId?: string;
  preauth: boolean;
  createdAt: number;
  lastSeen: number;
  absoluteExpiresAt: number;
};
type Recovery = { code: string; expiresAt: number };
type Failure = { count: number; lockedUntil: number };

const sessions = new Map<string, Session>();
const failures = new Map<string, Failure>();

const account = {
  id: "account_marcus_demo",
  email: "marcus@example.test",
  phone: "+15551234567",
  identityConfirmed: false,
  mfaEnabled: false,
  encryptedSecret: undefined as string | undefined,
  acceptedCounter: undefined as bigint | undefined,
  encryptedRecoveryCodes: undefined as string | undefined,
};

function token(bytes = 32) {
  return randomBytes(bytes).toString("base64url");
}
function equal(a: string, b: string) {
  const x = Buffer.from(a), y = Buffer.from(b);
  return x.length === y.length && timingSafeEqual(x, y);
}
function encrypt(value: string) {
