  let bits = 0, value = 0;
  const out: number[] = [];
  if (!/^[A-Z2-7]+$/.test(secret)) throw new Error("invalid secret");
  for (const ch of secret) {
    value = (value << 5) | BASE32.indexOf(ch); bits += 5;
    if (bits >= 8) { out.push((value >>> (bits - 8)) & 255); bits -= 8; }
  }
  return Buffer.from(out);
}
